import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { roomAPI, bookingAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';

const OwnerDashboard = () => {
  const { user } = useAuth();
  const [rooms, setRooms] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState({
    rooms: true,
    bookings: true,
    stats: true
  });
  const [newRoom, setNewRoom] = useState({
    title: '',
    description: '',
    capacity: '',
    price_per_hour: '',
    address: '',
    city: '',
    postal_code: '',
    country: 'France'
  });
  const [showRoomForm, setShowRoomForm] = useState(false);

  useEffect(() => {
    if (user) {
      fetchOwnerData();
    }
  }, [user]);

  const fetchOwnerData = async () => {
    await Promise.all([
      fetchOwnerRooms(),
      fetchOwnerBookings(),
      fetchOwnerStats()
    ]);
  };

  const fetchOwnerRooms = async () => {
    try {
      const response = await roomAPI.getOwnerRooms();
      setRooms(response.data.rooms || []);
    } catch (error) {
      console.error('Erreur chargement salles:', error);
    } finally {
      setLoading(prev => ({ ...prev, rooms: false }));
    }
  };

  const fetchOwnerBookings = async () => {
    try {
      const response = await bookingAPI.getOwnerBookings();
      setBookings(response.data.bookings || []);
    } catch (error) {
      console.error('Erreur chargement réservations:', error);
    } finally {
      setLoading(prev => ({ ...prev, bookings: false }));
    }
  };

  const fetchOwnerStats = async () => {
    try {
      const response = await roomAPI.getOwnerStats();
      setStats(response.data.stats);
    } catch (error) {
      console.error('Erreur chargement stats:', error);
    } finally {
      setLoading(prev => ({ ...prev, stats: false }));
    }
  };

  const handleNewRoomChange = (e) => {
    setNewRoom({
      ...newRoom,
      [e.target.name]: e.target.value
    });
  };

  const handleAddRoom = async (e) => {
    e.preventDefault();
    try {
      const response = await roomAPI.create(newRoom);
      if (response.success) {
        setRooms([...rooms, response.data.room]);
        setNewRoom({
          title: '',
          description: '',
          capacity: '',
          price_per_hour: '',
          address: '',
          city: '',
          postal_code: '',
          country: 'France'
        });
        setShowRoomForm(false);
        fetchOwnerStats(); // Rafraîchir les stats
      }
    } catch (error) {
      console.error('Erreur création salle:', error);
    }
  };

  const handleConfirmBooking = async (bookingId) => {
    try {
      const response = await bookingAPI.confirm(bookingId);
      if (response.success) {
        // Rafraîchir les réservations
        fetchOwnerBookings();
      }
    } catch (error) {
      console.error('Erreur confirmation:', error);
    }
  };

  const handleDeleteRoom = async (roomId) => {
    if (!window.confirm('Supprimer cette salle ?')) return;
    
    try {
      const response = await roomAPI.delete(roomId);
      if (response.success) {
        setRooms(rooms.filter(r => r.id !== roomId));
        fetchOwnerStats();
      }
    } catch (error) {
      console.error('Erreur suppression:', error);
    }
  };

  return (
    <div className="main-content">
      <div className="card">
        <h1>Espace Propriétaire</h1>
        <p>Bienvenue dans votre espace de gestion, <strong>{user?.first_name}</strong></p>
      </div>

      {/* Statistiques */}
      <div className="card">
        <h2>📊 Statistiques</h2>
        {loading.stats ? (
          <p>Chargement des statistiques...</p>
        ) : stats ? (
          <div className="stats-grid">
            <div className="stat-card">
              <h3>{stats.total_rooms || 0}</h3>
              <p>Salles totales</p>
            </div>
            <div className="stat-card">
              <h3>{stats.available_rooms || 0}</h3>
              <p>Salles disponibles</p>
            </div>
            <div className="stat-card">
              <h3>{bookings.length}</h3>
              <p>Réservations</p>
            </div>
            <div className="stat-card">
              <h3>{stats.total_revenue || 0}€</h3>
              <p>Revenus totaux</p>
            </div>
          </div>
        ) : (
          <p>Aucune statistique disponible</p>
        )}
      </div>

      {/* Gestion des salles */}
      <div className="card">
        <div className="section-header">
          <h2>🏢 Mes salles ({rooms.length})</h2>
          <button 
            onClick={() => setShowRoomForm(!showRoomForm)}
            className="btn btn-primary"
          >
            {showRoomForm ? 'Annuler' : '+ Ajouter une salle'}
          </button>
        </div>

        {showRoomForm && (
          <form onSubmit={handleAddRoom} className="room-form">
            <h3>Nouvelle salle</h3>
            <div className="form-row">
              <div className="form-group">
                <label>Titre *</label>
                <input
                  type="text"
                  name="title"
                  value={newRoom.title}
                  onChange={handleNewRoomChange}
                  required
                  className="form-input"
                />
              </div>
              <div className="form-group">
                <label>Ville *</label>
                <input
                  type="text"
                  name="city"
                  value={newRoom.city}
                  onChange={handleNewRoomChange}
                  required
                  className="form-input"
                />
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label>Capacité *</label>
                <input
                  type="number"
                  name="capacity"
                  value={newRoom.capacity}
                  onChange={handleNewRoomChange}
                  required
                  className="form-input"
                  min="1"
                />
              </div>
              <div className="form-group">
                <label>Prix/heure (€) *</label>
                <input
                  type="number"
                  name="price_per_hour"
                  value={newRoom.price_per_hour}
                  onChange={handleNewRoomChange}
                  required
                  className="form-input"
                  min="0"
                  step="0.01"
                />
              </div>
            </div>

            <div className="form-group">
              <label>Adresse *</label>
              <input
                type="text"
                name="address"
                value={newRoom.address}
                onChange={handleNewRoomChange}
                required
                className="form-input"
              />
            </div>

            <div className="form-group">
              <label>Description</label>
              <textarea
                name="description"
                value={newRoom.description}
                onChange={handleNewRoomChange}
                className="form-input"
                rows="3"
              />
            </div>

            <button type="submit" className="btn btn-primary">
              Créer la salle
            </button>
          </form>
        )}

        {loading.rooms ? (
          <p>Chargement des salles...</p>
        ) : rooms.length > 0 ? (
          <div className="rooms-list">
            {rooms.map(room => (
              <div key={room.id} className="room-item">
                <div className="room-info">
                  <h4>{room.title}</h4>
                  <p>{room.city} • {room.capacity} pers. • {room.price_per_hour}€/h</p>
                  <p className="room-status">
                    {room.is_available ? '✅ Disponible' : '❌ Indisponible'}
                  </p>
                </div>
                <div className="room-actions">
                  <Link to={`/rooms/${room.id}`} className="btn btn-secondary btn-sm">
                    Voir
                  </Link>
                  <button 
                    onClick={() => handleDeleteRoom(room.id)}
                    className="btn btn-secondary btn-sm"
                  >
                    Supprimer
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p>Vous n'avez pas encore créé de salles.</p>
        )}
      </div>

      {/* Réservations en attente */}
      <div className="card">
        <h2>📅 Réservations en attente</h2>
        
        {loading.bookings ? (
          <p>Chargement des réservations...</p>
        ) : bookings.filter(b => b.status === 'pending').length > 0 ? (
          <div className="bookings-list">
            {bookings
              .filter(b => b.status === 'pending')
              .map(booking => (
                <div key={booking.id} className="booking-item">
                  <div className="booking-info">
                    <h4>Réservation #{booking.id}</h4>
                    <p>Client: {booking.client_first_name} {booking.client_last_name}</p>
                    <p>Salle: {booking.room_title}</p>
                    <p>Date: {new Date(booking.start_datetime).toLocaleDateString('fr-FR')}</p>
                    <p>Prix: {booking.total_price}€</p>
                  </div>
                  <div className="booking-actions">
                    <button 
                      onClick={() => handleConfirmBooking(booking.id)}
                      className="btn btn-primary btn-sm"
                    >
                      Confirmer
                    </button>
                  </div>
                </div>
              ))}
          </div>
        ) : (
          <p>Aucune réservation en attente.</p>
        )}
      </div>
    </div>
  );
};

export default OwnerDashboard;
